import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Project vision","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/vision.md","filePath":"en/game-design/vision.md"}'),i={name:"en/game-design/vision.md"};function n(s,e,l,d,p,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="project-vision" tabindex="-1">Project vision <a class="header-anchor" href="#project-vision" aria-label="Permalink to &quot;Project vision&quot;">​</a></h1><p><strong>Design status: Accepted. Implementation: existing UO foundation with experimental localized combat; broader systems remain proposals. Verification: design review, not a current availability report.</strong></p><p>SyroUO Lab prioritizes fast, safe gameplay prototyping with ModernUO, ClassicUO and legally obtained UO assets. Validate play before replacing mature infrastructure. A future standalone game is conditional on Lab results, not a current rewrite requirement.</p><p>Combat should remain approachable through automatic attacks while optional advanced interaction rewards both player judgment and character capability. The same principles should apply to PvP and PvM where anatomy allows. Gear should be meaningful, replaceable and primarily horizontal rather than an endless power ladder.</p><p>Keep concepts such as anatomy separate from legacy animation categories. Cheap abstractions can support legacy and custom providers together; speculative independence must not slow the first playable experiment.</p><p><strong>Gap:</strong> extended gameplay validation remains incomplete. Design approval does not establish available features or validated balance.</p><p><a href="/Syrolands-Public/en/game-design/combat/overview.html">Combat</a> · Lab decision · Roadmap</p><h2 id="proposed-living-world-pillar" tabindex="-1">Proposed living-world pillar <a class="header-anchor" href="#proposed-living-world-pillar" aria-label="Permalink to &quot;Proposed living-world pillar&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/living-world.html">Living world and world materials</a> proposes persistent environmental changes through shared material rules: forestry, fire, terrain, magic and later ecology. Its sparse simulation architecture and candidate prototype remain Proposed, with unresolved protection and regeneration policies. This adds no Accepted decision or implementation scope to the current combat slice.</p><h2 id="proposed-combat-direction-—-batch-05" tabindex="-1">Proposed combat direction — Batch 05 <a class="header-anchor" href="#proposed-combat-direction-—-batch-05" aria-label="Permalink to &quot;Proposed combat direction — Batch 05&quot;">​</a></h2><p>The earlier Accepted automatic foundation above records the existing experiment. The newer <a href="/Syrolands-Public/en/game-design/combat/legacy-and-modern.html">Legacy/Modern proposal</a> makes Modern player-triggered cadence the preferred experimental direction while preserving Legacy automatic cadence as a supported fallback/accessibility/nostalgia option. This preference is Proposed, not approval or delivery of a replacement system; shared resource rules and viable Legacy play remain constraints.</p><p><a href="/Syrolands-Public/en/guide/introduction.html">Player introduction</a> presents the world, combat, knowledge, craft, magic and multiple-endgame pillars as a concise reading path; proposals retain their existing status.</p>',12)])])}const g=a(i,[["render",n]]);export{h as __pageData,g as default};
